function zbl.DNASystem.Get(ply)
    local steamid = zclib.Player.GetID(ply)
    if zbl.DNAPoints[steamid] and zbl.DNAPoints[steamid].points then
        return zbl.DNAPoints[steamid].points
    else
        return 0
    end
end
